import Foundation
import XCTest
@testable import CoachApp

/// Run only with the private, disposable fixture generated by the isolated test runner.
@MainActor
final class RealConnectionTests: XCTestCase {
    private func fixture() throws -> [String: String] {
        let bundle = Bundle(for: Self.self)
        let url = try XCTUnwrap(bundle.url(forResource: "IsolatedFixture", withExtension: "plist"))
        return try XCTUnwrap(NSDictionary(contentsOf: url) as? [String: String])
    }

    func test1PairAndSave() async throws {
        let values = try fixture()
        let model = ConnectionModel()
        let start = ContinuousClock.now
        await model.pair(address: try XCTUnwrap(values["base"]), code: try XCTUnwrap(values["code"]))
        print("Pair and authenticated hello elapsed: \(start.duration(to: .now))")
        guard case .connected = model.state else { XCTFail("Pair did not reach connected state"); return }
        XCTAssertNotNil(try CredentialStore(service: "coach.ton1411.device").load())
    }

    func test2RestoreAndRevoke() async throws {
        let values = try fixture()
        let store = CredentialStore(service: "coach.ton1411.device")
        defer { try? store.delete() }
        let (address, credential) = try XCTUnwrap(store.load())
        let model = ConnectionModel()
        let start = ContinuousClock.now
        await model.restore()
        print("Restored authenticated hello elapsed: \(start.duration(to: .now))")
        guard case .connected = model.state else { XCTFail("Restored credential was not accepted"); return }

        var revoke = URLRequest(url: address.url.appendingPathComponent("v1/devices/\(credential.deviceId)"))
        revoke.httpMethod = "DELETE"
        revoke.setValue("Bearer \(try XCTUnwrap(values["adminToken"]))", forHTTPHeaderField: "Authorization")
        revoke.setValue("desktop", forHTTPHeaderField: "X-Coach-Device")
        let (_, response) = try await URLSession.shared.data(for: revoke)
        XCTAssertEqual((response as? HTTPURLResponse)?.statusCode, 204)
        await model.reconnect()
        guard case .revoked = model.state else { XCTFail("Revoked credential was not rejected"); return }
    }
}
